def safe_integer(text):
    try:
        return int(text)
    except ValueError:
        return None

assert safe_integer("12") == 12
assert safe_integer("twelve") is None
print("Practice checks passed")

books = [{"title": "Mti wa Hadithi", "available": True}]

def find_title(records, phrase):
    phrase = phrase.strip().lower()
    if not phrase:
        return None
    for record in records:
        if phrase in record["title"].lower():
            return record
    return None

match = find_title(books, "mti")
if match is not None:
    print(f"Found: {match['title']}")
else:
    print("No match")
